import { code } from '../../../code.ts';
import { iosClass, pascal } from '../../names.ts';
import type { RegistryValues } from '../../values.ts';

// The path of the file in plugins/ios.
export const path = () => 'src/PluginRegistry.mm';

export default ({ plugins }: RegistryValues) => code`
// clang-format off
// Generated by plugins/tools/generate.ts from plugins/plugins/*/plugin.json; do not edit.
#import <PluginRegistry/PluginRegistry.h>

${plugins.map(({ id }) => `#import <${pascal(id)}/${pascal(id)}.h>`).join('\n')}

NSErrorDomain const MLNPluginRegistryErrorDomain = @"org.maplibre.plugins";
const NSInteger MLNPluginRegistryErrorUnknownPlugin = 1;

@implementation MLNPluginRegistry

+ (NSArray<NSString *> *)pluginIdentifiers {
    return @[
${plugins.map(({ id }) => `        @"${id}",`).join('\n')}
    ];
}

+ (BOOL)registerPluginWithIdentifier:(NSString *)identifier error:(NSError **)error {
${plugins
  .map(
    ({ id }) => `    if ([identifier isEqualToString:@"${id}"]) {
        return [${iosClass(id)} registerPluginWithError:error];
    }`,
  )
  .join('\n')}
    if (error) {
        *error = [NSError errorWithDomain:MLNPluginRegistryErrorDomain
                                     code:MLNPluginRegistryErrorUnknownPlugin
                                 userInfo:@{
                                     NSLocalizedDescriptionKey:
                                         [NSString stringWithFormat:@"No plugin has the identifier %@", identifier]
                                 }];
    }
    return NO;
}

@end
`;
